PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS scent_club_members (id INTEGER PRIMARY KEY AUTOINCREMENT, member_code TEXT NOT NULL UNIQUE, email_normalized TEXT NOT NULL, first_name TEXT, plan TEXT NOT NULL CHECK(plan IN ('essential','signature','duo')), status TEXT NOT NULL DEFAULT 'active', selection_mode TEXT NOT NULL DEFAULT 'curated' CHECK(selection_mode IN ('self_select','curated')), preference_gender TEXT DEFAULT 'Unisex', started_at TEXT, next_renewal_at TEXT, blocked INTEGER NOT NULL DEFAULT 0, pending_action TEXT, pending_action_at TEXT, cancellation_reason TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_scent_member_login ON scent_club_members(member_code,email_normalized);
CREATE TABLE IF NOT EXISTS scent_club_sessions (token_hash TEXT PRIMARY KEY, member_id INTEGER NOT NULL, csrf_token TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(member_id) REFERENCES scent_club_members(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS scent_club_login_attempts (key_hash TEXT PRIMARY KEY, failures INTEGER NOT NULL DEFAULT 0, window_started_at TEXT NOT NULL, locked_until TEXT);
CREATE TABLE IF NOT EXISTS scent_club_products (reference TEXT PRIMARY KEY, gender TEXT NOT NULL, image TEXT, profile TEXT, description TEXT, active INTEGER NOT NULL DEFAULT 1, discontinued INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS scent_club_selections (id INTEGER PRIMARY KEY AUTOINCREMENT, member_id INTEGER NOT NULL, month INTEGER NOT NULL, year INTEGER NOT NULL, product_reference TEXT NOT NULL, selected_at TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'self_service', UNIQUE(member_id,month,year), FOREIGN KEY(member_id) REFERENCES scent_club_members(id));
CREATE TABLE IF NOT EXISTS scent_club_events (id INTEGER PRIMARY KEY AUTOINCREMENT, member_id INTEGER NOT NULL, event_type TEXT NOT NULL, metadata TEXT, created_at TEXT NOT NULL, FOREIGN KEY(member_id) REFERENCES scent_club_members(id));
CREATE TABLE IF NOT EXISTS scent_club_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, member_id INTEGER NOT NULL, task_type TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', metadata TEXT, created_at TEXT NOT NULL, FOREIGN KEY(member_id) REFERENCES scent_club_members(id));
